/** Replaced at build time with the shown version in release-version.json. */
declare const __KORA_VERSION__: string;
/** A unique id for this build; the deployed /build.json holds the newest one. */
declare const __KORA_BUILD_ID__: string;
/** The Music Companion version this build bundles and installs (empty when none was packaged). */
declare const __KORA_COMPANION_VERSION__: string;
